import test from'node:test';import assert from'node:assert/strict';import {quoteSpot,compareIndicativeQuotes}from'../quote.mjs';import {demoSnapshot}from'../demo.mjs';import {NOW,clone}from'./fixtures.mjs';
const snapshot=()=>demoSnapshot('injective',NOW), sell=(s=snapshot(),amount='1000000000000000000',more={})=>quoteSpot(s,{side:'sell-base',inputAtomic:amount,...more},{now:NOW});
test('sell across two levels deducts quote-denominated taker fees exactly',()=>{const q=sell();assert.equal(q.quoteNotionalAtomic,'9500000');assert.equal(q.tradingFeeQuoteAtomic,'19000');assert.equal(q.estimatedOutputAfterTradingFeeAtomic,'9481000');assert.equal(q.fillStatus,'filled');assert.equal(q.fills.length,2);});
test('buy uses quote budget including fee, rounding down the affordable lot count',()=>{const q=quoteSpot(snapshot(),{side:'buy-base',inputAtomic:'11022000'},{now:NOW});assert.equal(q.baseFilledAtomic,'1000000000000000000');assert.equal(q.remainingInputAtomic,'0');assert.equal(q.tradingFeeQuoteAtomic,'22000');});
test('buy budget that cannot cover a whole lot returns explicit residual input',()=>{const q=quoteSpot(snapshot(),{side:'buy-base',inputAtomic:'11021999'},{now:NOW});assert.equal(q.baseFilledAtomic,'990000000000000000');assert.notEqual(q.remainingInputAtomic,'0');assert.equal(q.fullInputConsumed,false);});
test('insufficient visible liquidity cannot be labeled a complete fill',()=>{const q=sell(snapshot(),'10000000000000000000');assert.equal(q.fillStatus,'depth-exhausted');assert.equal(q.remainingInputAtomic,'7500000000000000000');});
test('sell below lot size keeps the unspent amount, never rounds up',()=>{const q=sell(snapshot(),'1');assert.equal(q.baseFilledAtomic,'0');assert.equal(q.remainingInputAtomic,'1');assert.equal(q.fullInputConsumed,false);});
test('limit price excludes worse levels instead of silently ignoring the bound',()=>{const q=sell(snapshot(),'1000000000000000000',{limitPrice:'10'});assert.equal(q.fillStatus,'limit-reached');assert.equal(q.baseFilledAtomic,'500000000000000000');});
test('buy price cap can exclude every ask',()=>{const q=quoteSpot(snapshot(),{side:'buy-base',inputAtomic:'1000000',limitPrice:'10'},{now:NOW});assert.equal(q.baseFilledAtomic,'0');assert.equal(q.estimatedOutputAfterTradingFeeAtomic,null);});
test('minimum notional is evaluated after a partial fill',()=>{const s=snapshot();s.market.minNotionalQuote={numerator:'1000000000',denominator:'1'};assert.equal(sell(s).fillStatus,'below-minimum-notional');assert.equal(sell(s).estimatedOutputAfterTradingFeeAtomic,null);});
test('unknown HyperCore fee is not zero and prevents net comparison',()=>{const q=quoteSpot(demoSnapshot('hypercore',NOW),{side:'sell-base',inputAtomic:'100000000'},{now:NOW});assert.equal(q.tradingFeeQuoteAtomic,null);assert.equal(q.estimatedOutputAfterTradingFeeAtomic,null);assert.equal(q.outputBeforeTradingFeeAtomic,'9500000');assert.ok(compareIndicativeQuotes([q],{now:NOW}).rejected[0].reasons.includes('UNKNOWN_TRADING_FEE'));});
test('fee rounding is conservative and hypothetical slippage is not a guaranteed minimum',()=>{const q=sell(snapshot(),'1000000000000000000',{slippageBps:100});assert.equal(q.hypotheticalSlippageFloorAtomic,'9386190');assert.equal(q.fillGuaranteed,false);assert.equal(q.globallyOptimal,false);});
test('expired snapshot and wall clock rollback are rejected',()=>{for(const now of [NOW-1,NOW+30001])assert.throws(()=>quoteSpot(snapshot(),{side:'sell-base',inputAtomic:'1'},{now}),/EXPIRED/);});
test('no trade, delivered wallet asset or complete costs are claimed',()=>{const q=sell();assert.equal(q.executable,false);assert.equal(q.deliveredToWallet,false);assert.equal(q.additionalCostsKnown,false);assert.equal(q.gasAndWithdrawalCostAtomic,null);});
test('comparison sorts net-of-trading-fee estimates but does not claim net best',()=>{const a=sell(),b=clone(a);b.estimatedOutputAfterTradingFeeAtomic='9500000';const r=compareIndicativeQuotes([a,b],{now:NOW});assert.equal(r.ranking[0].index,1);assert.equal(r.netBest,null);assert.equal(r.executable,false);});
test('same symbol on a different chain, token or balance location is not comparable',()=>{const a=sell();for(const field of ['id','location','amount']){const b=clone(a);if(field==='id')b.outputAsset.id+='-wrapped';if(field==='location')b.balanceLocation+='-wallet';if(field==='amount')b.inputAtomic='1';assert.ok(compareIndicativeQuotes([a,b],{now:NOW}).rejected.some(x=>x.index===1));}});
test('partial fills and stale quotes are excluded from ranking',()=>{const a=sell(),b=sell(snapshot(),'10000000000000000000');assert.equal(compareIndicativeQuotes([a,b],{now:NOW}).ranking.length,1);assert.equal(compareIndicativeQuotes([a],{now:NOW+30001}).ranking.length,0);});
test('large buy quantity is solved using integer search with no floating point',()=>{const s=snapshot();s.asks=[{price:{numerator:'1',denominator:'1'},baseAtomic:'1000000000000000000000000000000'}];s.market.lotAtomic='1';s.market.takerFeeRate={numerator:'0',denominator:'1'};const q=quoteSpot(s,{side:'buy-base',inputAtomic:'9007199254740993'},{now:NOW});assert.equal(q.baseFilledAtomic,'9007199254740993');});
test('zero fill caused by a price bound preserves its reason even below minimum notional',()=>{const q=quoteSpot(snapshot(),{side:'buy-base',inputAtomic:'1000000',limitPrice:'10'},{now:NOW});assert.equal(q.fillStatus,'limit-reached');});
